function BOX_DIMENSION(points, scales):
    for each eps in scales:
        cells <- empty set
        for each p in points:
            cells.insert( floor(p / eps) )
        N[eps] <- |cells|
    xs <- [ log(1/eps)   for eps in scales ]
    ys <- [ log(N[eps])  for eps in scales ]
    return SLOPE_LEAST_SQUARES(xs, ys)

function ITERATE(f, n):
    return x |-> apply f to x exactly n times

function ITERATE_CONSTANTS(K, K_anti, n):
    return (K^n, K_anti^n)            # finite => f^[n] bi-Lipschitz

function HOLDER_CORRIDOR(dim_s, r, n):
    return dim_s / r^n               # upper wall on dimH(f^[n](s))

